import {summary, topicStats, plan, validateState} from './model.js';
const KEY='orbita-fisica-v1', sourceSheet='https://docs.google.com/spreadsheets/d/1DeDYw247uwjkEPRu7F7G-aFJENacZg-1yEdjeG4rA-E/edit';
const seed=await fetch('./seed.json').then(r=>r.json()), roadmaps=await fetch('./roadmaps.json').then(r=>r.json());
let state=structuredClone(seed), loadError=false;
try {const saved=localStorage.getItem(KEY);if(saved)state=validateState(JSON.parse(saved));}catch{loadError=true;}
let view='dashboard',filter='Todos',query='',trailTab='temas',week=1,undo=null,toastTimer;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const fmt=(n,d=0)=>Number(n||0).toLocaleString('pt-BR',{maximumFractionDigits:d});
const date=(v,short=false)=>v?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:short?'short':'long',...(short?{}:{year:'numeric'}),timeZone:'UTC'}).format(new Date(v+'T12:00:00Z')):'A definir';
const uid=()=>crypto.randomUUID(), safeURL=u=>{try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?x.href:'';}catch{return '';}};
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',route:'M5 4v12a4 4 0 0 0 4 4h9M5 8h11a4 4 0 0 0 0-8M18 17l3 3-3 3',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3zM12 6v15',check:'m5 12 4 4L19 6',list:'M9 5h12M9 12h12M9 19h12M3 4h2v2H3zM3 11h2v2H3zM3 18h2v2H3z',chart:'M4 20V10M10 20V4M16 20v-8M22 20H2',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16',compare:'M9 3 5 7l4 4M5 7h14M15 13l4 4-4 4M19 17H5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',external:'M14 3h7v7M21 3 11 13M10 5H4v15h15v-6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',edit:'m16 3 5 5-12 12-6 1 1-6zM13 6l5 5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',pause:'M9 5v14M15 5v14',note:'M4 3h12l4 4v14H4zM15 3v5h5M8 12h8M8 16h6',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const link=(url,label,cls='text-link')=>safeURL(url)?`<a class="${cls}" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${label}${icon('external',13)}</a>`:'';
const btn=(label,action,cls='secondary',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const badge=(s,c='muted')=>`<span class="badge ${c}">${esc(s)}</span>`;
const progress=p=>`<div class="progress-track"><span style="width:${Math.min(100,p)}%"></span></div>`;
const headings={dashboard:['Visão geral','Cada passo conta. Cada descoberta também.'],trail:['Sua trilha de estudos','Uma base sólida, construída um assunto de cada vez.'],library:['Sua biblioteca','O conhecimento que você já tem, conectado ao próximo passo.'],practice:['Exercícios e simulados','Resolva, corrija, entenda. Transforme erros em aprendizado.'],performance:['Seu desempenho','Evidências reais para orientar o que estudar depois.'],scenarios:['Dois caminhos. Um objetivo.','Compare o ritmo necessário para cada cenário de ingresso.'],deadlines:['Seleções e prazos','EUF e doutorado UFC: acompanhe cada frente com clareza.'],notes:['Caderno de bordo','Ideias, descobertas e perguntas que merecem ficar.'],settings:['Ajustes do planejamento','Seu plano deve acompanhar a sua vida.'],search:['Buscar no seu espaço','Encontre temas, livros e atividades.']};
const topicColors=['#8275bd','#b78d5e','#639b96','#bf8e9b','#8499b6','#9c8cb9','#8b9a72','#b28b7b','#6d9dac'];
const currentStats=()=>topicStats({...state,tasks:state.tasks.filter(t=>t.scenario==='both'||t.scenario===state.settings.scenario)});
const topics=()=>[...new Set([...state.tasks.map(t=>t.topic),...state.materials.map(m=>m.topic),...state.sessions.map(s=>s.topic)])].sort();
const matches=o=>!query||JSON.stringify(o).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'));
function persist(message='Alterações salvas',previous=true){try{state=validateState(state);localStorage.setItem(KEY,JSON.stringify(state));loadError=false;if(previous)notify(message,true);render();}catch(e){notify('Não foi possível salvar: '+e.message);render();}}
function change(fn,message){undo=structuredClone(state);fn();persist(message);}
function notify(message,canUndo=false){clearTimeout(toastTimer);$('#toast').innerHTML=esc(message)+(canUndo?` <button data-action="undo">Desfazer</button>`:'');$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function navigate(next){view=next;filter='Todos';query='';week=1;render();window.scrollTo({top:0,behavior:'instant'});}
function taskRow(t,planned=false){return `<div class="task-row"><button class="check ${t.done?'checked':''}" data-action="toggle-task" data-id="${esc(t.id)}" aria-label="${t.done?'Reabrir':'Concluir'}: ${esc(t.title)}" aria-pressed="${t.done}">${t.done?icon('check',14):''}</button><div class="task-info ${t.done?'completed':''}"><button class="plain-title" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button><small>${esc(t.topic)} <span>·</span> ${fmt(t.hours,1)} h${planned&&t.plannedDate?' · '+date(t.plannedDate,true):''}</small></div>${badge(t.done?'Concluído':t.scenario==='both'?'Base comum':t.scenario,t.done?'green':'muted')}<button class="icon-button subtle" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Editar atividade">${icon('edit',15)}</button></div>`;}
function orbitArt(){return `<svg viewBox="0 0 350 230" role="img" aria-label="Ilustração de órbitas e estrelas"><defs><radialGradient id="planet"><stop stop-color="#f8f6ff"/><stop offset="1" stop-color="#c3b8e8"/></radialGradient></defs><g transform="translate(185 118)"><circle r="80" fill="#e8e3f4"/><circle r="52" fill="none" stroke="#d2c9e7"/><ellipse rx="133" ry="48" transform="rotate(-28)" fill="none" stroke="#9986bc" stroke-width="1.3"/><ellipse rx="109" ry="71" transform="rotate(40)" fill="none" stroke="#c4b8da" stroke-dasharray="3 5"/><circle r="38" fill="url(#planet)"/><ellipse rx="133" ry="48" transform="rotate(-28)" fill="none" stroke="#9986bc" stroke-width="1.3" stroke-dasharray="170 500"/><circle cx="-109" cy="64" r="10" fill="#dba580"/><circle cx="83" cy="-68" r="6" fill="#7867a6"/><circle cx="74" cy="75" r="5" fill="#a1b3a3"/></g><g fill="#a79aba"><circle cx="55" cy="51" r="2"/><circle cx="299" cy="183" r="2"/><circle cx="260" cy="25" r="2"/></g><path d="M70 170v12m-6-6h12M297 66v12m-6-6h12" stroke="#aa98bf" stroke-width="1.4"/><text x="42" y="111" fill="#9d8dae" font-family="Georgia,serif" font-size="20" font-style="italic">ψ</text><text x="284" y="153" fill="#a698b7" font-family="Georgia,serif" font-size="15">ℏ</text></svg>`;}
function sidebar(){const nav=[['dashboard','home','Visão geral'],['trail','route','Trilha de estudos'],['library','book','Biblioteca'],['practice','list','Exercícios e simulados'],['performance','chart','Desempenho'],['scenarios','compare','Comparar cenários'],['deadlines','calendar','Seleções e prazos'],['notes','note','Caderno de bordo']];return `<aside class="sidebar"><a href="#" class="brand" data-nav="dashboard"><img class="brand-mark" src="./favicon.svg" alt=""><div><span class="brand-name">órbita<span class="brand-dot">.</span></span><span class="brand-sub">SEU ESPAÇO DE ESTUDOS</span></div></a><div class="workspace-tag">${icon('spark',16)} Física · EUF & Doutorado <span>⌄</span></div><p class="nav-group-label">MEU PLANEJAMENTO</p><nav>${nav.map(([v,i,l])=>`<button class="nav-item ${view===v?'active':''}" data-nav="${v}">${icon(i)}<span>${l}</span>${v==='library'?`<span class="nav-count">${state.materials.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><span class="small-orbit">✧</span><strong>Um passo de cada vez.</strong><p>O próximo capítulo começa com curiosidade.</p></div><button class="nav-item ${view==='settings'?'active':''}" data-nav="settings">${icon('settings')}<span>Ajustes e backup</span></button><div class="user-block"><span class="user-avatar">MC</span><div class="user-meta"><strong>${esc(state.settings.name)}</strong><small>Meu espaço pessoal</small></div><span class="online-dot"></span></div></div></aside>`;}
function scenarioSwitch(){return `<div class="scenario-switch" aria-label="Cenário de ingresso">${['2027.2','2028.1'].map(s=>`<button class="${s===state.settings.scenario?'active':''}" data-action="scenario" data-id="${s}">Ingresso ${s}</button>`).join('')}</div>`;}
function dashboard(){const s=summary(state), ps=plan(state,state.settings.scenario);if(ps.length&&week<Math.min(...ps.map(t=>t.week)))week=Math.min(...ps.map(t=>t.week));const list=ps.filter(t=>t.week===week), ts=currentStats().filter(t=>t.total), ds=state.deadlines.filter(d=>d.scenario===state.settings.scenario||d.scenario==='both').sort((a,b)=>a.date.localeCompare(b.date));return `<div class="hero-grid"><section class="hero"><div class="hero-copy"><span class="chip"><span class="status-dot"></span>${state.settings.status==='standby'?'PLANEJAMENTO EM STAND-BY':'PREPARAÇÃO EM ANDAMENTO'}</span><h2>Seu próximo capítulo<br>começa aqui.</h2><p>Da curiosidade à conquista, ${esc(state.settings.name)}.<br>Organize seu caminho até o doutorado em Física.</p>${btn(state.settings.status==='standby'?'Quero começar '+icon('arrow'):'Continuar minha trilha '+icon('arrow'),state.settings.status==='standby'?'activate':'go-trail','primary')}<span class="hero-meta">${icon('calendar',14)}Referência inicial: ${date(state.settings.startDate,true)}</span></div><div class="hero-art">${orbitArt()}</div></section><section class="focus-card"><div class="focus-top">${icon('target',21)}<span>NO SEU HORIZONTE</span></div><h3>Doutorado em Física</h3><p>Universidade Federal do Ceará</p><div class="focus-intake"><strong>${state.settings.scenario}</strong>${badge('Ingresso desejado','purple')}</div><div class="focus-bottom"><span>${s.weeks} semanas planejadas</span><span>${fmt(state.settings.scenarios[state.settings.scenario].hours)} h / semana</span></div>${progress(s.percent)}<div class="focus-progress"><span>Trilha concluída</span><strong>${s.percent}%</strong></div></section></div>
<div class="stats-grid">${stat('clock','Horas de estudo',fmt(s.studyHours,1)+'<small> h</small>','de '+fmt(s.goalHours)+' h planejadas','purple')}${stat('check','Atividades concluídas',s.completed+'<small> / '+s.total+'</small>','Seu avanço na trilha','green')}${stat('list','Questões resolvidas',fmt(s.questions),'Cada questão é uma descoberta','orange')}${stat('chart','Taxa de acerto',s.accuracy===null?'—':fmt(s.accuracy)+'<small>%</small>',s.questions?'Sobre questões registradas':'Aguardando seu primeiro registro','purple')}</div>
<div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Seu próximo passo</h2><p>Uma semana de cada vez, no seu ritmo.</p></div>${btn('Ver trilha '+icon('arrow',15),'go-trail','ghost small')}</div><div class="week-label"><span>${icon('calendar',16)} Semana ${week} <span class="muted-text">· ${list[0]?date(list[0].plannedDate,true):'Plano concluído'}</span></span><div><button class="icon-button" data-action="prev-week" aria-label="Semana anterior">‹</button><button class="icon-button" data-action="next-week" aria-label="Próxima semana">›</button></div></div><div class="task-list">${list.length?list.slice(0,5).map(t=>taskRow(t)).join(''):empty('Tudo em dia por aqui','Explore a trilha ou cadastre uma nova atividade.')}</div><div class="panel-footer">${icon('spark',15)} ${state.settings.status==='standby'?'Prévia do plano. Nenhum estudo foi iniciado automaticamente.':'As próximas semanas se ajustam às atividades pendentes.'}</div></section><section class="panel"><div class="panel-header"><h2>Avanço por assunto</h2><button class="icon-button" data-nav="performance" aria-label="Ver desempenho">${icon('arrow')}</button></div><div class="panel-body">${ts.slice(0,5).map((t,i)=>`<div class="topic-row"><div><span class="topic-dot" style="background:${topicColors[i]}"></span><span>${esc(t.topic)}</span><strong>${t.percent}%</strong></div>${progress(t.percent)}</div>`).join('')}<p class="small muted-text">Conclusão de atividades · acertos em Desempenho</p></div></section></div>
<div class="dashboard-grid bottom-grid"><section><div class="section-heading"><h2>Na sua estante</h2><button class="text-link" data-nav="library">Explorar biblioteca ${icon('arrow',15)}</button></div><div class="cards-grid compact">${state.materials.filter(m=>m.type==='Livro físico').filter(m=>['B054','B056','newbook0'].includes(m.id)).slice(0,3).map(materialCard).join('')}</div></section><section class="panel"><div class="panel-header"><h2>No radar</h2>${badge('Datas estimadas','orange')}</div><div class="panel-body">${ds.slice(0,3).map(milestone).join('')}<button class="text-link" data-nav="deadlines">Ver seleções e prazos ${icon('arrow',15)}</button></div></section></div>`;}
function stat(i,l,v,f,c){return `<section class="stat-card"><div class="stat-top"><span class="stat-label">${l}</span><span class="stat-icon ${c}">${icon(i,17)}</span></div><div class="stat-value">${v}</div><div class="stat-foot">${f}</div></section>`;}
function empty(title,description){return `<div class="empty-state">${icon('spark',28)}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;}
function materialCard(m,i=0){const color=topicColors[i%topicColors.length];return `<article class="material-card"><button class="material-cover ${m.type==='Livro físico'?'physical':'digital'}" style="--cover:${color}" data-action="edit-material" data-id="${esc(m.id)}" aria-label="Abrir ${esc(m.title)}">${m.type==='Livro físico'?`<div class="book-spine"><small>MINHA BIBLIOTECA</small><strong>${esc(m.title)}</strong><span>${esc(m.author||'Acervo pessoal')}<i>○</i></span></div>`:`<div class="digital-icon">${icon(m.type==='Simulado'?'target':m.type==='Lista'?'list':m.type==='Videoaula'?'spark':'note',38)}<span>${esc(m.type)}</span></div>`}</button><div class="material-body"><div class="material-tags">${badge(m.type,m.type==='Livro físico'?'orange':'purple')}${m.answerUrl?badge('Com gabarito','green'):''}</div><h3><button class="plain-title" data-action="edit-material" data-id="${esc(m.id)}">${esc(m.title)}</button></h3><p>${esc(m.topic)}</p><div class="card-actions">${link(m.url,'Abrir','text-link')||`<span class="small muted-text">${esc(m.status)}</span>`}<button class="icon-button" data-action="edit-material" data-id="${esc(m.id)}" aria-label="Editar material">${icon('edit',15)}</button></div></div></article>`;}
function toolbar(options,placeholder){return `<div class="toolbar"><div class="search-field">${icon('search')}<input id="view-search" data-search placeholder="${placeholder}" value="${esc(query)}" aria-label="${placeholder}"></div><select id="filter" aria-label="Filtrar resultados">${options.map(t=>`<option ${filter===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
function library(practice=false){let ms=state.materials.filter(m=>!practice||['Lista','Simulado'].includes(m.type)).filter(matches).filter(m=>filter==='Todos'||m.type===filter);return `${practice?`<div class="notice green">${icon('check',21)}<div><strong>Treino com correção, desde o começo.</strong><p>Seus cadernos autorais já estão aqui: 120 problemas, 16 exemplos e simulados com gabaritos. A prova histórica oficial aparece identificada separadamente.</p></div></div>`:''}${toolbar(practice?['Todos','Lista','Simulado']:['Todos',...new Set(state.materials.map(m=>m.type))],'Buscar por título, assunto ou autor…')}<div class="results-meta">${ms.length} ${practice?'atividades':'materiais'} <span>· ${practice?'Registre acertos por assunto para acompanhar suas lacunas.':'Livros físicos, arquivos e aulas no mesmo lugar.'}</span></div>${practice?`<div class="practice-list">${ms.map(m=>`<article class="panel practice-card"><div class="practice-icon">${icon(m.type==='Simulado'?'target':'list',25)}</div><div class="practice-main"><div>${badge(m.type,'purple')} ${badge(m.answerUrl?'Com gabarito':'Gabarito pendente',m.answerUrl?'green':'orange')}</div><h3>${esc(m.title)}</h3><p>${esc(m.notes)}</p><div class="card-actions">${link(m.url,'Abrir atividade')}${link(m.answerUrl,'Ver gabarito')}${btn('Registrar resultado','record','primary small',`data-id="${esc(m.id)}"`)}<button class="icon-button" data-action="edit-material" data-id="${esc(m.id)}" aria-label="Editar atividade">${icon('edit',15)}</button></div></div></article>`).join('')}</div>`:`<div class="cards-grid library-grid">${ms.map(materialCard).join('')}</div>`}${!ms.length?empty('Nenhum material encontrado','Experimente outro filtro ou adicione um material.'):''}`;}
function trail(){const ts=currentStats(), relevant=state.tasks.filter(t=>t.scenario==='both'||t.scenario===state.settings.scenario), ps=plan(state,state.settings.scenario);return `<div class="view-tabs"><button class="${trailTab==='temas'?'active':''}" data-trail="temas">${icon('list',16)} Por assunto</button><button class="${trailTab==='semanas'?'active':''}" data-trail="semanas">${icon('calendar',16)} Plano ajustável</button><button class="${trailTab==='original'?'active':''}" data-trail="original">${icon('book',16)} Roteiro original</button></div>${trailTab==='original'?`<div class="notice">${icon('book',20)}<div><strong>Seu roteiro de referência · ${state.settings.scenario}</strong><p>Importado da planilha em 18/11/2026. Datas e cargas são projeções históricas. O plano ajustável usa os seus registros e configurações atuais.</p></div></div>${roadmaps['Trilha'+state.settings.scenario].filter(r=>r[0]&&/^[AB]\d+$/.test(r[0])).map(r=>`<details class="topic-card original-week"><summary><span class="badge purple">${esc(r[0])}</span><div class="topic-summary"><strong>${esc(r[3].split('\n')[0])}</strong><small>${esc(r[1])} a ${esc(r[2])} · ${esc(r[6])} h previstas</small></div><span>⌄</span></summary><div class="reference-detail"><h4>Entrega</h4><p>${esc(r[5])}</p><h4>Materiais e listas</h4><p>${esc(r[4])}</p><h4>Prática prioritária</h4><p>${esc(r[11])}</p><h4>Exemplos resolvidos</h4><p>${esc(r[10])}</p>${btn('Criar atividade a partir desta semana','new-task','secondary small',`data-prefill="${esc(r[3])}"`)}</div></details>`).join('')}`:trailTab==='semanas'?`<div class="notice">${icon('spark',20)}<div><strong>O plano acompanha seus resultados</strong><p>Atividades pendentes são distribuídas pela carga semanal. Assuntos com menor acerto ganham prioridade; prazos manuais são preservados. As estimativas das atividades cobrem uma primeira passagem, não a meta completa de horas de revisão.</p></div></div>${!ps.length?empty('Trilha concluída','Adicione novas revisões ou atividades quando precisar.'):Array.from(new Set(ps.map(t=>t.week))).map(w=>`<section class="panel weekly-panel"><div class="panel-header"><h2>Semana ${w}</h2>${badge(fmt(ps.filter(t=>t.week===w).reduce((a,t)=>a+t.hours,0),1)+' h previstas','purple')}</div>${ps.filter(t=>t.week===w).map(t=>taskRow(t,true)).join('')}</section>`).join('')}`:`${toolbar(['Todos',...ts.filter(t=>t.total).map(t=>t.topic)],'Buscar na sua trilha…')}${ts.filter(t=>t.total&&(filter==='Todos'||filter===t.topic)).map((t,i)=>{const tasks=relevant.filter(x=>x.topic===t.topic).filter(matches);return tasks.length?`<details class="topic-card" ${query||i===0?'open':''}><summary><span class="topic-icon" style="color:${topicColors[i%9]};background:${topicColors[i%9]}18">${icon(i===0?'route':'book',22)}</span><div class="topic-summary"><strong>${esc(t.topic)}</strong><small>${tasks.filter(x=>x.done).length} de ${tasks.length} atividades concluídas</small></div><div class="topic-stats"><span>${t.percent}%</span>${progress(t.percent)}</div><span class="chevron">⌄</span></summary><div class="task-list">${tasks.map(x=>taskRow(x)).join('')}</div></details>`:'';}).join('')}`}`;}
function performance(){const s=summary(state), ts=topicStats(state).filter(t=>t.total||t.questions);return `<div class="stats-grid">${stat('clock','Horas registradas',fmt(s.studyHours,1)+'<small> h</small>',state.sessions.length+' sessões de estudo','purple')}${stat('list','Questões respondidas',fmt(s.questions),fmt(s.correct)+' acertos registrados','green')}${stat('chart','Acerto geral',s.accuracy===null?'—':fmt(s.accuracy)+'<small>%</small>','Média ponderada pelo total de questões','orange')}${stat('target','Meta de horas',fmt(s.goalHours)+'<small> h</small>','Cenário '+state.settings.scenario,'purple')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>Acerto por assunto</h2>${badge('Dados reais','green')}</div><div class="panel-body chart-bars">${ts.map(t=>`<div class="chart-row"><div class="chart-label"><span>${esc(t.topic)}</span><strong>${t.accuracy===null?'Sem dados':fmt(t.accuracy)+'%'}</strong></div><div class="chart-track"><span style="width:${t.accuracy||0}%;background:${t.accuracy!==null&&t.accuracy<60?'#d2a17a':'#9081c9'}"></span></div><small class="muted-text">${t.questions?`${t.correct} / ${t.questions} questões · `:''}${fmt(t.hours,1)} h registradas</small></div>`).join('')}</div></section><section class="panel"><div class="panel-header"><h2>Para orientar sua revisão</h2></div><div class="panel-body">${ts.filter(t=>t.questions).length?ts.filter(t=>t.questions).sort((a,b)=>a.accuracy-b.accuracy).slice(0,4).map(t=>`<div class="recommendation">${icon('target',19)}<div><strong>${esc(t.topic)}</strong><p>${fmt(t.accuracy)}% em ${t.questions} questões. ${t.accuracy<70?'Revisite os erros antes de avançar.':'Retome com questões inéditas e revisão espaçada.'}</p></div></div>`).join(''):empty('Seu mapa está se formando','Registre questões por assunto. O plano usará esses resultados para priorizar revisões.')}<p class="small muted-text">A taxa de acerto não é uma probabilidade de aprovação. Quantidade, dificuldade e repetição das questões influenciam a leitura.</p></div></section></div><section class="panel sessions-panel"><div class="panel-header"><h2>Diário de estudos</h2>${btn(icon('plus',16)+' Registrar estudo','record','primary small')}</div>${state.sessions.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Assunto</th><th>Tempo</th><th>Acertos</th><th>Notas e erros</th><th></th></tr></thead><tbody>${[...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${date(r.date,true)}</td><td>${esc(r.topic)}</td><td>${fmt(r.hours,1)} h</td><td>${r.total?`${r.correct}/${r.total}`:'—'}</td><td class="notes-cell">${esc(r.notes||'—')}</td><td><button class="icon-button" data-action="edit-session" data-id="${esc(r.id)}" aria-label="Editar registro">${icon('edit',16)}</button></td></tr>`).join('')}</tbody></table></div>`:empty('A primeira sessão começa com você','Horas e resultados só aparecem depois que você registrar um estudo.')}</section>`;}
function scenarios(){return `<div class="notice">${icon('compare',20)}<div><strong>Seu aprendizado acompanha os dois caminhos.</strong><p>As atividades de base comum e as horas estudadas contam nos dois cenários. A comparação mostra a cobertura da trilha e o esforço para cada meta; não duplica registros nem estima chance de aprovação.</p></div></div><div class="comparison-grid">${['2027.2','2028.1'].map(sc=>{const s=summary(state,sc),h=state.settings.scenarios[sc];return `<section class="scenario-card ${sc===state.settings.scenario?'selected':''}"><div class="scenario-card-top">${badge(sc===state.settings.scenario?'Cenário em foco':'Cenário alternativo',sc===state.settings.scenario?'purple':'muted')}${icon('target',24)}</div><div class="scenario-number">${sc}</div><p>${sc==='2027.2'?'Uma preparação mais concentrada.':'Mais espaço para aprofundar e revisar.'}</p><div class="scenario-metrics"><div><span>Janela de preparação</span><strong>${s.weeks} semanas</strong></div><div><span>Carga configurada</span><strong>${fmt(h.hours,1)} h / semana</strong></div><div><span>Meta total</span><strong>${fmt(h.goalHours)} h</strong></div><div><span>Horas registradas</span><strong>${fmt(s.studyHours,1)} h</strong></div><div><span>Ritmo necessário na janela restante</span><strong>${s.requiredWeeklyHours===null?'Prazo encerrado':fmt(s.requiredWeeklyHours,1)+' h / semana'}</strong></div><div><span>Fim projetado da preparação</span><strong>${date(h.target,true)}</strong></div></div><div class="focus-progress"><span>Atividades concluídas</span><strong>${s.percent}%</strong></div>${progress(s.percent)}<p class="scenario-capacity">${s.feasible?'○ A carga comporta a meta de horas.':'△ A meta exige ajustar a carga ou o prazo.'}</p>${btn(sc===state.settings.scenario?'Cenário selecionado':'Usar este cenário','scenario',sc===state.settings.scenario?'secondary':'primary',`data-id="${sc}"`)}</section>`;}).join('')}</div><div class="notice orange">${icon('clock',20)}<div><strong>Compatibilize o plano com a docência.</strong><p>A rotina mais recente da sua planilha sugere 16 h/sem no recesso e 9 h/sem no semestre. As cargas de 16 h e 12 h aqui preservam os cenários originais e podem ser alteradas nos ajustes.</p>${btn('Ajustar cargas e datas','go-settings','ghost small')}</div></div>`;}
function milestone(d){return `<div class="milestone"><div class="milestone-date"><strong>${d.date.slice(8)}</strong><span>${new Intl.DateTimeFormat('pt-BR',{month:'short',timeZone:'UTC'}).format(new Date(d.date+'T12:00Z')).replace('.','')}</span></div><div class="milestone-body"><strong>${esc(d.title)}</strong><small>${d.status==='official'?'Data oficial cadastrada':'Estimativa · confirmar no edital'}</small></div><button class="icon-button" data-action="edit-deadline" data-id="${esc(d.id)}" aria-label="Editar prazo">${icon('edit',15)}</button></div>`;}
function deadlines(){return `<div class="notice orange">${icon('calendar',22)}<div><strong>Editais dos ingressos 2027.2 e 2028.1: aguardados.</strong><p>As datas iniciais são referências provisórias do seu planejamento, não prazos oficiais. Atualize cada marco quando o edital for publicado. Esta página não consulta calendários automaticamente.</p></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>Marcos do cenário ${state.settings.scenario}</h2></div><div class="panel-body">${state.deadlines.filter(d=>d.scenario===state.settings.scenario||d.scenario==='both').sort((a,b)=>a.date.localeCompare(b.date)).map(d=>`<div>${milestone(d)}${link(d.url,'Consultar fonte','text-link milestone-source')}</div>`).join('')||empty('Sem marcos cadastrados','Adicione uma data para acompanhar este cenário.')}</div></section><section class="panel"><div class="panel-header"><h2>Fontes oficiais</h2></div><div class="panel-body official-links">${link('https://www1.fisica.org.br/~euf/index.php/pt/','Calendário e editais do EUF')}${link('https://www1.fisica.org.br/~euf/images/edital_euf_2-2026.pdf','Programa EUF · referência 2-2026')}${link('https://www1.fisica.org.br/~euf/index.php/pt/plataform-access','Provas e gabaritos anteriores')}${link('https://www.fisica.ufc.br/portal/pos/','Seleções da Física UFC')}${link('https://www.fisica.ufc.br/portal/pos/formas-de-ingresso/','UFC · formas de ingresso')}<p class="small muted-text">Fontes consultadas em 18/11/2026.</p></div></section></div><div class="notice">${icon('book',22)}<div><strong>EUF e doutorado UFC são frentes distintas.</strong><p>A referência atual do doutorado UFC envolve histórico, projeto/defesa e currículo. O EUF não está sendo tratado como requisito obrigatório para esse doutorado. Confirme os critérios no edital do seu ingresso. Provas do mestrado são apenas treino complementar.</p></div></div>`;}
function settings(){return `<div class="settings-grid"><section class="panel"><div class="panel-header"><h2>Um plano do seu tamanho</h2></div><form id="settings-form" class="panel-body"><div class="form-grid">${field('name','Como quer ser chamado','text',state.settings.name)}${field('startDate','Data-base da preparação','date',state.settings.startDate)}${selectField('status','Estado do planejamento',[['standby','Em stand-by'],['active','Em andamento']],state.settings.status)}${selectField('scenario','Cenário principal',[['2027.2','2027.2'],['2028.1','2028.1']],state.settings.scenario)}${['2027.2','2028.1'].map(sc=>`<div class="field full scenario-form-heading"><h3>Ingresso ${sc}</h3><p>Metas ajustáveis; não são datas oficiais de seleção.</p></div>${field('target-'+sc,'Fim da preparação','date',state.settings.scenarios[sc].target)}${field('hours-'+sc,'Horas por semana','number',state.settings.scenarios[sc].hours,'min="0.5" max="168" step="0.5"')}${field('goal-'+sc,'Meta de estudo (horas)','number',state.settings.scenarios[sc].goalHours,'min="1" max="10000" step="1"')}`).join('')}</div><div class="form-save">${btn('Salvar e reajustar plano','submit','primary','type="submit"')}</div></form></section><div><section class="panel"><div class="panel-header"><h2>Seus dados, com você</h2></div><div class="panel-body"><p>As alterações ficam salvas neste navegador. Para continuar em outro dispositivo ou endereço, exporte o backup e importe-o lá.</p><div class="backup-actions">${btn(icon('download')+' Exportar backup','export','primary')}${btn('Importar backup','import','secondary')}</div><p class="small muted-text">O arquivo JSON inclui materiais, registros, checklists, notas e configurações. A importação substitui os dados atuais após uma prévia.</p></div></section><section class="panel source-panel"><div class="panel-header"><h2>Planejamento de origem</h2></div><div class="panel-body"><p>Base importada da sua planilha em 18/11/2026. Novas alterações no site e no Drive são independentes.</p>${link(sourceSheet,'Abrir planilha de estudos')}${link('https://drive.google.com/drive/folders/18XCUoRUH9zQ6DImWuv3_ZNbzlDhd1Tdb','Abrir pasta de materiais')}<p class="small muted-text">O site está preparado para hospedagem estática no GitHub Pages. Os dados de estudo são locais ao navegador e não são gravados no repositório.</p></div></section></div></div>`;}
function notes(){return `<section class="panel notebook"><div class="panel-header"><h2>Notas pessoais</h2><span id="note-save" class="small muted-text">Salvo neste navegador</span></div><div class="panel-body"><textarea id="personal-notes" aria-label="Notas pessoais" placeholder="Escreva suas ideias, dúvidas e próximos passos…">${esc(state.notes)}</textarea></div></section><div class="notice">${icon('note',20)}<div><strong>Deixe um rastro do seu raciocínio.</strong><p>Registre erros específicos junto de cada sessão, em Desempenho. Use este caderno para reflexões gerais e ideias do projeto.</p></div></div>`;}
function search(){const ts=state.tasks.filter(matches),ms=state.materials.filter(matches);return `${toolbar(['Todos'],'Buscar em todo o espaço…')}<div class="section-heading"><h2>Atividades (${ts.length})</h2></div><section class="panel">${ts.slice(0,15).map(t=>taskRow(t)).join('')||empty('Nenhuma atividade encontrada','Experimente outras palavras.')}</section><div class="section-heading"><h2>Materiais (${ms.length})</h2></div><div class="cards-grid">${ms.slice(0,18).map(materialCard).join('')}</div>`;}
function render(){const focus=document.activeElement?.id,caret=document.activeElement?.selectionStart;const s=summary(state);$('#app').innerHTML=`${sidebar()}<button class="mobile-overlay" data-action="menu" aria-label="Fechar menu"></button><main class="main-shell"><header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><span>Meu espaço</span><span>/</span><strong>${headings[view][0]}</strong></div><div class="top-actions"><button class="icon-button" data-nav="search" aria-label="Buscar em todo o espaço">${icon('search')}</button><span class="save-status"><span class="status-dot"></span>Salvo neste navegador</span>${btn(icon('plus',16)+' Registrar estudo','record','primary small')}</div></header><div class="content"><div class="page-heading"><div><p class="eyebrow">${view==='dashboard'?'BEM-VINDO AO SEU ESPAÇO':'MEU PLANEJAMENTO'}</p><h1>${view==='dashboard'?'Vamos construir o seu caminho.':headings[view][0]}</h1><p>${headings[view][1]}</p></div><div class="heading-actions">${['dashboard','trail','scenarios','deadlines'].includes(view)?scenarioSwitch():['library','practice'].includes(view)?btn(icon('plus',16)+' Adicionar '+(view==='library'?'material':'atividade'),'new-material','primary'):view==='settings'||view==='notes'||view==='search'?'':btn(icon('plus',16)+' Registrar estudo','record','secondary')}${view==='trail'?btn(icon('plus',16)+' Nova atividade','new-task','secondary small'):view==='deadlines'?btn(icon('plus',16)+' Novo marco','new-deadline','secondary small'):''}</div></div>${loadError?`<div class="notice orange"><div><strong>O backup local não pôde ser lido.</strong><p>Seus dados anteriores não foram apagados. Exporte uma cópia antes de salvar alterações.</p>${btn('Recuperar arquivo local','export-raw','secondary small')}</div></div>`:''}${({dashboard,trail,library,practice:()=>library(true),performance,scenarios,deadlines,notes,settings,search})[view]()}<footer class="page-footer"><span>órbita<span> · </span>Conhecimento em movimento.</span><span>${state.settings.status==='standby'?'Planejamento em stand-by':'Preparação em andamento'} <span>·</span> ${s.percent}% da trilha</span></footer></div></main>`;if(focus&&document.getElementById(focus)){document.getElementById(focus).focus();if(caret!==null&&document.getElementById(focus).setSelectionRange)try{document.getElementById(focus).setSelectionRange(caret,caret);}catch{}}}
function field(name,label,type,value='',extra='',required=true){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`;}
function selectField(name,label,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;}
function textarea(name,label,value=''){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" rows="4">${esc(value)}</textarea></div>`;}
function openModal(title,body,submit='Salvar',kind='',id=''){const d=$('#modal');d.innerHTML=`<form id="modal-form" data-kind="${kind}" data-id="${esc(id)}"><div class="modal-header"><h2>${title}</h2><button type="button" class="icon-button close-button" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}<p class="form-error" id="form-error" role="alert"></p></div><div class="modal-footer">${id?btn('Excluir','delete','danger small',`type="button" data-kind="${kind}" data-id="${esc(id)}"`):''}<span class="footer-spacer"></span>${btn('Cancelar','close','secondary','type="button"')}<button type="submit" class="button primary">${submit}</button></div></form>`;d.showModal();}
function materialModal(id){const m=state.materials.find(m=>m.id===id)||{type:view==='practice'?'Lista':'Livro físico',topic:'Geral',status:'Não iniciado'};openModal(id?'Editar material':'Adicionar à biblioteca',`<div class="form-grid">${field('title','Título','text',m.title)}${selectField('type','Tipo',[...new Set(['Livro físico','Videoaula','Lista','Simulado','PDF','Projeto','Link',...state.materials.map(m=>m.type)])],m.type)}${selectField('topic','Assunto',topics(),m.topic)}${field('author','Autor ou origem','text',m.author,'',false)}${field('url','Link do material (opcional)','url',m.url,'placeholder="https://…"',false)}${field('answerUrl','Link do gabarito (opcional)','url',m.answerUrl,'placeholder="https://…"',false)}${selectField('status','Status',['Não iniciado','Em uso','Concluído','Referência'],m.status)}${textarea('notes','Capítulos, páginas e observações',m.notes)}</div>`, 'Salvar material','material',id||'');}
function taskModal(id,prefill=''){const t=state.tasks.find(t=>t.id===id)||{title:prefill,hours:2,topic:topics()[0],scenario:'both'};openModal(id?'Editar atividade':'Nova atividade de estudo',`<div class="form-grid">${field('title','Atividade ou entrega','text',t.title)}${selectField('topic','Assunto',topics(),t.topic)}${field('newTopic','Ou criar novo assunto','text','','placeholder="Opcional"',false)}${field('hours','Horas estimadas','number',t.hours,'min="0.25" max="10000" step="0.25"')}${selectField('scenario','Conta para',[['both','Os dois cenários'],['2027.2','2027.2'],['2028.1','2028.1']],t.scenario)}${field('due','Prazo manual (opcional)','date',t.due,'',false)}${selectField('materialId','Material associado',[['','Nenhum'],...state.materials.map(m=>[m.id,m.title])],t.materialId||'')}${textarea('notes','Entrega, evidências e revisões',t.notes)}</div>${t.materialId?link(state.materials.find(m=>m.id===t.materialId)?.url,'Abrir material associado'):''}`,'Salvar atividade','task',id||'');}
function sessionModal(id,activityId=''){const r=state.sessions.find(s=>s.id===id)||{date:today(),topic:state.materials.find(m=>m.id===activityId)?.topic||topics()[0],hours:1,correct:0,total:0,activityId};openModal(id?'Editar registro':'Registrar estudo',`${state.settings.status==='standby'?'<p class="notice small">Seu plano está em stand-by. Registre apenas estudos que você realmente realizou.</p>':''}<div class="form-grid">${field('date','Data do estudo','date',r.date)}${selectField('topic','Assunto avaliado',topics(),r.topic)}${field('hours','Tempo estudado (horas)','number',r.hours,'min="0.05" max="24" step="0.05"')}${selectField('activityId','Material ou atividade',[['','Estudo livre'],...state.materials.map(m=>[m.id,m.title])],r.activityId||'')}${field('total','Questões tentadas','number',r.total,'min="0" max="10000" step="1"')}${field('correct','Questões corretas','number',r.correct,'min="0" max="10000" step="1"')}${textarea('notes','O que aprendi, erros e próxima revisão',r.notes)}</div><p class="small muted-text">Para simulados com vários assuntos, registre cada assunto separadamente e divida o tempo total entre os registros. Para estudo teórico, deixe as questões em zero.</p>`,'Salvar registro','session',id||'');}
function deadlineModal(id){const d=state.deadlines.find(d=>d.id===id)||{scenario:state.settings.scenario,status:'estimate'};openModal(id?'Editar marco':'Novo marco do planejamento',`<div class="form-grid">${field('title','Marco ou etapa','text',d.title)}${field('date','Data','date',d.date)}${selectField('scenario','Cenário',[['both','Os dois cenários'],['2027.2','2027.2'],['2028.1','2028.1']],d.scenario)}${selectField('status','Natureza da data',[['estimate','Estimativa / meta pessoal'],['official','Oficial — confirmada no edital']],d.status)}${field('url','Fonte ou edital','url',d.url,'placeholder="https://…"',false)}</div>`,'Salvar marco','deadline',id||'');}
let pendingImport;
document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-nav],[data-trail]');if(!target)return;e.preventDefault();if(target.dataset.nav){navigate(target.dataset.nav);return;}if(target.dataset.trail){trailTab=target.dataset.trail;render();return;}const a=target.dataset.action,id=target.dataset.id;if(a==='submit'){target.closest('form').requestSubmit();return;}if(a==='close')return $('#modal').close();if(a==='menu')return $('.sidebar').classList.toggle('open');if(a==='go-trail')return navigate('trail');if(a==='go-settings')return navigate('settings');if(a==='undo'&&undo){state=undo;undo=null;persist('Alteração desfeita',false);return notify('Alteração desfeita');}if(a==='scenario'){change(()=>state.settings.scenario=id,'Cenário atualizado');week=1;return;}if(a==='activate')return openModal('Seu primeiro passo',`<p>O planejamento está em stand-by. Ao começar, você ativa sua trilha e define a data-base. Nenhuma atividade será marcada como concluída.</p><div class="form-grid">${field('startDate','Quando começa a sua preparação?','date',state.settings.startDate)}</div>`,'Quero começar','activate');if(a==='toggle-task')return change(()=>{const t=state.tasks.find(t=>t.id===id);t.done=!t.done;},'Checklist atualizado · horas são registradas separadamente');if(a==='new-task'||a==='edit-task')return taskModal(id,target.dataset.prefill);if(a==='new-material'||a==='edit-material')return materialModal(id);if(a==='record'||a==='edit-session')return sessionModal(a==='edit-session'?id:null,a==='record'?id:'');if(a==='new-deadline'||a==='edit-deadline')return deadlineModal(id);if(a==='prev-week'){week=Math.max(1,week-1);return render();}if(a==='next-week'){week=Math.min(Math.max(...plan(state,state.settings.scenario).map(t=>t.week),1),week+1);return render();}if(a==='delete'){const key={material:'materials',task:'tasks',session:'sessions',deadline:'deadlines'}[target.dataset.kind];change(()=>state[key]=state[key].filter(x=>x.id!==id),'Item excluído');$('#modal').close();return;}if(a==='export'||a==='export-raw'){const content=a==='export-raw'?(localStorage.getItem(KEY)||JSON.stringify(state)):JSON.stringify(state,null,2);download(content,'orbita-backup-'+today()+'.json');return notify('Backup exportado');}if(a==='import')return $('#import-file').click();});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));try{if(form.id==='settings-form'){for(const sc of ['2027.2','2028.1'])if(data['target-'+sc]<data.startDate)throw new Error('O fim da preparação deve ser posterior à data-base.');change(()=>{state.settings={...state.settings,name:data.name,startDate:data.startDate,status:data.status,scenario:data.scenario,scenarios:Object.fromEntries(['2027.2','2028.1'].map(sc=>[sc,{target:data['target-'+sc],hours:+data['hours-'+sc],goalHours:+data['goal-'+sc]}]))};},'Plano reajustado');return;}if(form.id!=='modal-form')return;const kind=form.dataset.kind,id=form.dataset.id||uid();let obj,key;if(kind==='activate'){if(Object.values(state.settings.scenarios).some(s=>s.target<data.startDate))throw new Error('Ajuste os prazos dos cenários antes de iniciar nessa data.');change(()=>{state.settings.status='active';state.settings.startDate=data.startDate;},'Preparação ativada. Um passo de cada vez.');$('#modal').close();return;}if(kind==='import'){undo=structuredClone(state);state=pendingImport;persist('Backup importado');loadError=false;$('#modal').close();return;}if(kind==='material'){obj={...data,id};key='materials';}if(kind==='task'){const old=state.tasks.find(t=>t.id===id);obj={...data,id,hours:+data.hours,topic:data.newTopic.trim()||data.topic,done:old?.done||false};delete obj.newTopic;key='tasks';}if(kind==='session'){if(+data.correct>+data.total)throw new Error('Os acertos não podem superar as questões tentadas.');if(data.date>today())throw new Error('Registre apenas estudos já realizados.');obj={...data,id,hours:+data.hours,total:+data.total,correct:+data.correct};key='sessions';}if(kind==='deadline'){if(data.status==='official'&&!safeURL(data.url))throw new Error('Informe o link da fonte para uma data oficial.');obj={...data,id};key='deadlines';}const draft=structuredClone(state),at=draft[key].findIndex(x=>x.id===id);if(at===-1)draft[key].push(obj);else draft[key][at]=obj;const validated=validateState(draft);undo=structuredClone(state);state=validated;persist(kind==='session'?'Estudo registrado. Seu progresso foi atualizado.':'Alterações salvas');$('#modal').close();}catch(err){if($('#form-error'))$('#form-error').textContent=err.message;else notify(err.message);}});
let searchTimer,noteTimer;document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){clearTimeout(searchTimer);query=e.target.value;searchTimer=setTimeout(render,100);}if(e.target.id==='personal-notes'){state.notes=e.target.value;clearTimeout(noteTimer);$('#note-save').textContent='Salvando…';noteTimer=setTimeout(()=>{try{localStorage.setItem(KEY,JSON.stringify(state));if($('#note-save'))$('#note-save').textContent='Salvo neste navegador';}catch{notify('Não foi possível salvar as notas. Exporte um backup.');}},400);}});
document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render();}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>10000000)throw new Error('Use um backup de até 10 MB.');pendingImport=validateState(JSON.parse(await f.text()));openModal('Revisar importação',`<p>Este backup substituirá os dados deste navegador.</p><div class="import-summary">${pendingImport.tasks.length} atividades · ${pendingImport.materials.length} materiais · ${pendingImport.sessions.length} registros</div><p>Nome: <strong>${esc(pendingImport.settings.name)}</strong><br>Cenário: ${esc(pendingImport.settings.scenario)}</p><p class="small muted-text">Exporte seu backup atual antes de continuar se quiser preservar as duas versões.</p>`,'Importar e substituir','import');}catch(err){notify('Backup inválido: '+err.message);}});
function download(content,name){const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
render();
